import type { Asset, Hotspot, Page, TitleCard, Tree } from "./types";

// ── Asset path helpers (same convention as books 1–2) ──────────────────────
// Plates live in /public/pages/NN/ as webp, made in little-rabbit-style from
// tools/scenes-thanksgiving.json (M2). The vector layout art they replaced is
// still generated by tools/make-layout-art.mjs for any plate that has no webp.
export const ART_EXT = "webp";
const pageDir = (n: number) => `/pages/${String(n).padStart(2, "0")}`;

const bg = (n: number): Asset => ({
  id: `bg-${n}`,
  src: `${pageDir(n)}/background.${ART_EXT}`,
  alt: "",
});

const layer = (n: number, id: string, extra: Partial<Asset> = {}): Asset => ({
  id,
  src: `${pageDir(n)}/${id}.${ART_EXT}`,
  alt: "",
  ...extra,
});

/** Audio paths — narration is per-page per-language (PRD §4). */
export const narrationSrc = (pageId: number, lang: string) =>
  `/audio/${lang}/${String(pageId).padStart(2, "0")}.mp3`;
export const countSrc = (n: number, lang: string) =>
  `/audio/${lang}/count/${n}.mp3`;
export const sfxSrc = (name: string) => `/sfx/${name}.mp3`;
export const leafSrc = (id: string) => `/leaves/${id}.${ART_EXT}`; // little-rabbit-style/tools/cut-leaves.py

// ── The seven leaves, in the order they join the tree (PRD §4.1) ─────────────
// `color` is mirrored in tools/make-layout-art.mjs; it sets the look for checking
// red/orange and green/brown apart (PRD §9.5).
export const LEAVES = [
  { id: "red", color: "#D9573F" },
  { id: "orange", color: "#EE9C53" },
  { id: "yellow", color: "#F2C94C" },
  { id: "green", color: "#6E9457" },
  { id: "brown", color: "#9A6B45" },
  { id: "purple", color: "#9C7BC0" },
  { id: "golden", color: "#E8B62C", big: true },
] as const;

// ── Title card ──────────────────────────────────────────────────────────────
