  start: { zh: "开始", en: "Start" },
  // 小兔 in her scarf beside the full seven-leaf tree — part of the cover art;
  // the app overlays the text.
  background: { id: "bg-title", src: `/pages/00/background.${ART_EXT}`, alt: "" },
  layers: [],
