// Secondary lines (PRD §4.1): the leaf's color + the running count, folded into
// the read-aloud script rather than living only in the numeral badge.
const THE_RULE = { zh: "说声谢谢，贴片叶子。", en: "Say thank you, add a leaf." };
const LEAF_LINES = [
  { zh: "红叶子，一片！", en: "A red leaf. One!" },
  { zh: "橙叶子，两片！", en: "An orange leaf. Two!" },
  { zh: "黄叶子，三片！", en: "A yellow leaf. Three!" },
  { zh: "绿叶子，四片！", en: "A green leaf. Four!" },
  { zh: "棕叶子，五片！", en: "A brown leaf. Five!" },
  { zh: "紫叶子，六片！", en: "A purple leaf. Six!" },
  { zh: "金叶子，七片！", en: "A golden leaf. Seven!" },
];

// Hotspots are % of the stage {x,y = top-left, w,h}, measured on the real art.
// The thank-you pages (2–6, 8–10) share one room (PRD §6: tree left, 小兔
// centre, person right), so these are measured once.
const TREE: Hotspot = { x: 2, y: 7, w: 36, h: 71 };
const RABBIT: Hotspot = { x: 33, y: 42, w: 22, h: 50 }; // 小兔 and the leaf in her paws
const LEAF_START = { x: 51.5, y: 65 }; // where that leaf is drawn, so its flight starts on it
const ROOM_WINDOW: Hotspot = { x: 41, y: 5, w: 18, h: 30 };
// Page 11: the same tree, centred (little-rabbit-style/tools/compose-p11.py).
const COUNT_TREE: Hotspot = { x: 32, y: 7, w: 36, h: 71 };
const tree = (leaves: number, area: Hotspot = TREE): Tree => ({ area, leaves });

// Falling leaves outside the window — the book's recurring through-line extra,
// like book 2's moon (PRD §7.1). The window looks the same before and after
// every page's main tap, so this one may show above the reveal.
const windowLeaves = (hotspot: Hotspot) => ({
  flash: "window-leaves",
  sfx: "wind-chime",
  hotspot,
  aboveReveal: true,
});

/** One thank-you page (PRD §5 pages 3–6, 8, 9). Same composition every time. */
function thankPage(
  id: number,
  total: number,
  text: { zh: string; en: string },
  extras: Page["extras"] = [],
  sfx = "leaf-boop",
): Page {
  return {
    id,
    text,
    secondaryText: LEAF_LINES[total - 1],
    background: bg(id),
    layers: [layer(id, "scene-thanked", { className: "swap-to" })],
    interaction: {
      kind: "thank",
      sfx,
      to: "scene-thanked",
      total,
      counting: true,
      leafFrom: LEAF_START,
      hotspot: RABBIT,
    },
    tree: tree(total - 1),
    extras,
  };
}

